testcase.name:
test_web_cart_button_semantics_accepts_idiomatic_variants[
const target = document.body;
const button = document.createElement("button");
const label = "Add" + " to " + "cart";
button.append(label);
target.append(button);
]

test_web_cart_button_semantics_rejects_comments_dead_literals_and_unattached_buttons[
const unused = "Add to cart";
const app = document.querySelector("#app")!;
const button = document.createElement("button");
app.appendChild(button);
]

test_brandmark_accessibility_semantics_accepts_equivalent_implementations[
export function BrandMark(): HTMLElement {
 const mark = document.createElement("span");
 mark.setAttribute("role", "img");
 mark.setAttribute("aria-label", "HP-Fetcher");
 return mark;
}
]

test_brandmark_accessibility_semantics_accepts_equivalent_implementations[
export function BrandMark(): HTMLElement {
  const template = document.createElement("template");
  template.innerHTML = '<span role="img" aria-label="HP-Fetcher"><span aria-hidden="true">[</span>HP-Fetcher</span>';
  return template.content.firstElementChild as HTMLElement;
}
]
